No repository in this fixture implements billing."},{"id":"26e5b2de-1154-4f30-adce-a9a719102706","sourceId":"6a4ba0d9-7203-48a0-bbd5-ec90ce100e82","sourceName":"order-api","revision":"237510937b4388fc718b7e9f93869954950df1bb","path":"src/main/java/Orders.java","startLine":1,"endLine":18,"contentHash":"533356fbff3802cf2f9085bc881c774a08851267d02a4448e8cc7105feb2352c","spanHash":"fb97e2aa5ace7f6292dd5007aa417217edc8d0b828793f822b3d0666df87cf52","text":"// Synthetic transport interfaces; no actual HTTP server or Kafka driver is included.
record OrderPlaced(String orderId, String tenantId, long createdAtMillis) {}
interface EventPublisher { void publish(String topic, String key, OrderPlaced event); }
record Accepted(String orderId) {}

final class Orders {
  private final EventPublisher publisher;
  private final String topic;
  Orders(EventPublisher publisher, String configuredTopic) {
    this.publisher = publisher;
    this.topic = System.getenv().getOrDefault("ORDER_TOPIC", configuredTopic);
  }
  Accepted accept(String orderId, String tenantId) {
    var event = new OrderPlaced(orderId, tenantId, System.currentTimeMillis());
    publisher.publish(topic, tenantId + ":" + orderId, event);
    return new Accepted(orderId);
  }
}"},{"id":"057d5f18-b727-4841-b04b-08871b566e2e","sourceId":"507b8567-db4e-4542-aa1c-3cf6dc5dec1b","sourceName":"deployment-local","revision":"266b8b73fbf744f2df4395e223df13b7e7504ffe","path":"README.md","startLine":1,"endLine":5,"contentHash":"f7799ac2083913178985916e706fd1a49a274e19ae1ec0848f9dd3cd06703b27","spanHash":"5193b2c91d19d834b00c0f1ff290c36c6753b306b26153be340c7ace9ad6d86f","text":"# Local deployment declarations

